/*
 * The parameter catalogue: what can be mapped, and what its limits are.
 *
 * `catalogue.json` is generated by tools/gen-catalogue.mjs from a device's own
 * Web RCS bundle and store dump, so every range here is the device's statement
 * about itself rather than a number copied out of a PDF. Regenerate it against
 * a different firmware and the mappings keep working — the ids are structural.
 *
 * Ids are the dotted node path within a layer: `opacity.opacity`,
 * `cropping.classic.left`, `keying.enable`.
 */

import catalogue from './catalogue.json' with { type: 'json' };

const layerById = new Map(catalogue.layer.map((p) => [p.id, p]));
const groupById = new Map(catalogue.screenGroup.map((p) => [p.id, p]));

export const meta = {
  generatedFrom: catalogue.generatedFrom,
  device: catalogue.device,
  presetKeys: catalogue.presetKeys
};

export const layerParams = catalogue.layer;
export const screenGroupParams = catalogue.screenGroup;
export const enums = catalogue.enums;

/** Look up a layer parameter spec by id. */
export const layerSpec = (id) => layerById.get(id) ?? null;

/** Look up a screen-group parameter spec by id. */
export const groupSpec = (id) => groupById.get(id) ?? null;

/**
 * The spec for a target, whichever kind it is.
 *
 * Returns null for an unknown id rather than throwing, because profiles are
 * user-editable JSON and one stale binding should not take a show down — the
 * engine reports it and carries on with the rest.
 */
export function specFor(target) {
  if (!target) return null;
  if (target.kind === 'screenGroup') return groupSpec(target.param);
  return layerSpec(target.param);
}

/**
 * Parameters worth offering first in a mapping UI.
 *
 * Everything in the catalogue is mappable; this is only about what a long list
 * should put at the top. Chosen to match what a surface is actually for —
 * opacity on a fader, geometry on encoders, source and keying on buttons.
 */
export const SUGGESTED = [
  'opacity.opacity',
  'position.posH',
  'position.posV',
  'position.sizeH',
  'position.sizeV',
  'position.anchor',
  'source.inputNum',
  'cropping.classic.left',
  'cropping.classic.right',
  'cropping.classic.top',
  'cropping.classic.bottom',
  'cropping.classic.aspectOverride',
  'cropping.mask.left',
  'cropping.mask.right',
  'cropping.mask.top',
  'cropping.mask.bottom',
  'keying.enable',
  'keying.source'
];

/** A human label for a parameter id, for scribble strips and the mapping UI. */
export function label(id) {
  const parts = String(id).split('.');
  const last = parts[parts.length - 1];
  return last
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/^./, (c) => c.toUpperCase());
}

/** A short label that fits an MCU scribble cell. */
export function shortLabel(id) {
  const SHORT = {
    'opacity.opacity': 'Opacity',
    'position.posH': 'Pos H',
    'position.posV': 'Pos V',
    'position.sizeH': 'Size H',
    'position.sizeV': 'Size V',
    'position.anchor': 'Anchor',
    'source.inputNum': 'Source',
    'keying.enable': 'Key On',
    'keying.source': 'Key Src',
    'cropping.classic.left': 'Crop L',
    'cropping.classic.right': 'Crop R',
    'cropping.classic.top': 'Crop T',
    'cropping.classic.bottom': 'Crop B',
    'cropping.classic.aspectOverride': 'Aspect',
    'cropping.mask.left': 'Mask L',
    'cropping.mask.right': 'Mask R',
    'cropping.mask.top': 'Mask T',
    'cropping.mask.bottom': 'Mask B'
  };
  return SHORT[id] ?? label(id).slice(0, 7);
}
